/// <summary>
/// One item variant whose units getItemUnits should return.
/// </summary>
[DataContractAttribute]
class HSMobileOpsItemUnitsKey
{
    str itemId;
    str configId;
    str sizeId;
    str colorId;
    str styleId;

}

Method.Source:
[DataMemberAttribute('ItemId')]
public str parmItemId(str _value = itemId)
{
    itemId = _value;
